PV = {'p':100,'n':320,'b':330,'r':500,'q':900,'k':10000}
DIR = {'n':[-17,-15,-10,-6,6,10,15,17],'b':[-9,-7,7,9],'r':[-8,-1,1,8],'q':[-9,-7,7,9,-8,-1,1,8]}
def pseudo_moves(bd, white):
    moves=[]
    for i,p in enumerate(bd):
        if p=='.': continue
        if white and p.islower(): continue
        r,c=i//8,i%8
        low=p.lower()
        if low=='p':
            dir_=-1 if white else 1
            start=1 if white else 6
            promo=7 if white else 0
            one=i+dir_
            if 0<=one<64 and bd[one]=='.':
                rr=rank_of(one)
                if rr==promo:
                    for pr in ['q','r','b','n']:
                        moves.append((i,one,pr))
                else:
                    moves.append((i,one))
                    two=one+dir_
                    if r==start and 0<=two<64 and bd[two]=='.':
                        moves.append((i,two))
            for dc in [-1,1]:
                nc=c+dc; nt=one+dc
                if 0<=nt<64 and bd[nt]!='.':
                    tgt=bd[nt]
                    if (white and tgt.isupper()) or (not white and tgt.islower()):
                        rr=rank_of(nt)
                        if rr==promo:
                            for pr in ['q','r','b','n']:
                                moves.append((i,nt,pr))
                        else:
                            moves.append((i,nt))
        elif low=='n':
            for d in DIR['n']:
                ni=i+d
                if 0<=ni<64 and abs(rank_of(ni)-r)<=2 and abs(file_of(ni)-c)<=2:
                    tgt=bd[ni]
                    if tgt=='.' or ((white and tgt.isupper()) or (not white and tgt.islower())):
                        moves.append((i,ni))
        elif low in 'brq':
            for d in DIR[low]:
                ni=i+d
                steps=0
                while 0<=ni<64 and steps<=7:
                    tgt=bd[ni]
                    if tgt=='.':
                        moves.append((i,ni))
                    else:
                        if (white and tgt.isupper()) or (not white and tgt.islower()):
                            moves.append((i,ni))
                        break
                    ni+=d
                    steps+=1
        elif low=='k':
            for d in [-9,-8,-7,-1,1,7,8,9]:
                ni=i+d
                if 0<=ni<64 and abs(rank_of(ni)-r)<=1 and abs(file_of(ni)-c)<=1:
                    tgt=bd[ni]
                    if tgt=='.' or ((white and tgt.isupper()) or (not white and tgt.islower())):
                        moves.append((i,ni))
    return moves

