def material_score(bd, ws):
    s=0
    for i,p in enumerate(bd):
        if p=='.': continue
        v=PV[p.lower()]
        if p.isupper()==ws: s+=v+PST[p.upper()][i]
        else: s-=v+PST[p.upper()][63-i]
    return s
def in_check(bd,w):
    kp='K' if w else 'k'
    try: ksq=bd.index(kp)
    except ValueError: return False
    return attacked_by(bd,ksq,not w)
def legal_moves(bd,w):
    out=[]
    for m in pseudo_moves(bd,w):
        nb=apply(bd,m)
        if not in_check(nb,w): out.append(m)
    return out

